import{j as a,c as d,b as n,ag as h}from"./chunks/framework.CPnt7f93.js";const u=JSON.parse('{"title":"TuringThink 青少年编程","description":"","frontmatter":{},"headers":[],"relativePath":"kidsedu/2.python.md","filePath":"kidsedu/2.python.md","lastUpdated":1761215374000}'),e={name:"kidsedu/2.python.md"};function i(o,t,r,l,c,s){return n(),d("div",null,[...t[0]||(t[0]=[h('<h1 id="turingthink-青少年编程" tabindex="-1">TuringThink 青少年编程 <a class="header-anchor" href="#turingthink-青少年编程" aria-label="Permalink to &quot;TuringThink 青少年编程&quot;">​</a></h1><h2 id="机构简介" tabindex="-1">机构简介 <a class="header-anchor" href="#机构简介" aria-label="Permalink to &quot;机构简介&quot;">​</a></h2><p><code>TuringThink</code> 是一家领先的少儿编程教育公司，致力于激发创造力，逻辑思维能力和多维度的学习能力，通过有趣而实践的课程，我们帮助学生掌握编程技能，并培养他们解决问题的能力。以 &quot; <code>TuringThink</code> &quot; 为商标，象征着思考、探索和创新。引导学生独立思考、探索世界，鼓励他们在软件编程的旅程中追求创新，我们的使命是培养下一代创造者和创新者，在数字时代充分发挥他们的潜力。</p><h3 id="教学系统" tabindex="-1">教学系统 <a class="header-anchor" href="#教学系统" aria-label="Permalink to &quot;教学系统&quot;">​</a></h3><p>自主研发乐特思教学系统 <code>LETS</code> - (Learning Explorer Teaching System)。该系统实时记录学生学习情况，并对学习数据进行大数据分析和数据挖掘。教师可以获得学生的多维度学习数据，从而因材施教，为每个学生定制最适合自己的学习方案.</p><h3 id="课程体系" tabindex="-1">课程体系 <a class="header-anchor" href="#课程体系" aria-label="Permalink to &quot;课程体系&quot;">​</a></h3><p><code>TuringThink</code> 提供多样化的课程，涵盖了多个编程语言和工具，旨在满足不同年龄和技能水平的学生需求。</p><ol><li><code>NOIP C++</code> :精心设计的 <code>NOIP C++</code> 课程，为学生提供深入学习 <code>C++</code> 编程语言的机会。此课程为学生参加全国奥林匹克信息学竞赛做准备。</li><li><code>Python</code> : <code>Python</code> 课程专注于培养学生对 <code>Python</code> 的理解和运用能力。通过实践项目和创意应用的开发，学生将在动手实践中提高编程技能。</li><li><code>Scratch</code> : 适合初学者的 <code>Scratch</code> 课程通过图形化编程界面，让学生创作动画、游戏和互动故事。这将激发学生的创造力和逻辑思维。</li><li><code>EV3</code> : 利用乐高机器人套件 <code>EV3</code> 进行机器人编程和控制，培养学生解决问题和团队合作的关键技能。</li><li><code>WeDo</code> : 针对年幼学生的乐高编程套件，通过有趣的项目探索基础编程概念，让学生在乐趣中启发好奇心和学习兴趣。</li></ol><h2 id="少儿python与langchain-ai开发教学体系-8-15岁" tabindex="-1">少儿Python与LangChain AI开发教学体系（8-15岁） <a class="header-anchor" href="#少儿python与langchain-ai开发教学体系-8-15岁" aria-label="Permalink to &quot;少儿Python与LangChain AI开发教学体系（8-15岁）&quot;">​</a></h2><h2 id="一、教学体系设计理念" tabindex="-1">一、教学体系设计理念 <a class="header-anchor" href="#一、教学体系设计理念" aria-label="Permalink to &quot;一、教学体系设计理念&quot;">​</a></h2><p>本体系以“空间技能-数学能力-Python编程-AI开发”四维融合为核心，基于Uttal空间认知四维度模型（内在/外在、静态/动态）与Mix空间训练迁移理论，将LangChain AI工具拆解为少儿可理解的“AI辅助模块”（如代码助手、数据分析师、应用设计师），通过<strong>游戏化项目</strong>（如几何绘图、迷宫导航、智能小工具）实现：</p><ol><li>空间技能：从“坐标感知”（低阶）到“空间建模”（高阶），覆盖心理旋转、空间缩放等核心能力；</li><li>数学能力：同步渗透数线、比例、数据统计、函数逻辑，呼应Verdine纵向追踪研究中“空间预测数学”的核心结论；</li><li>编程与AI：Python从“语法入门”到“项目开发”，LangChain从“对话辅助”到“智能逻辑搭建”，降低AI开发门槛。</li></ol><h2 id="二、分阶段教学大纲-3阶段6级" tabindex="-1">二、分阶段教学大纲（3阶段6级） <a class="header-anchor" href="#二、分阶段教学大纲-3阶段6级" aria-label="Permalink to &quot;二、分阶段教学大纲（3阶段6级）&quot;">​</a></h2><h3 id="阶段1-启蒙阶-8-10岁-2级-——空间感知与python基础" tabindex="-1">阶段1：启蒙阶（8-10岁，2级）——空间感知与Python基础 <a class="header-anchor" href="#阶段1-启蒙阶-8-10岁-2级-——空间感知与python基础" aria-label="Permalink to &quot;阶段1：启蒙阶（8-10岁，2级）——空间感知与Python基础&quot;">​</a></h3><h4 id="核心目标" tabindex="-1">核心目标 <a class="header-anchor" href="#核心目标" aria-label="Permalink to &quot;核心目标&quot;">​</a></h4><p>掌握Python基础语法，通过“图形化编程+AI对话”理解空间坐标与数学数线的对应关系，培养<strong>内在-静态空间技能</strong>（如图形结构识别）。</p><table tabindex="0"><thead><tr><th>模块</th><th>核心内容</th><th>空间-数学融合点</th><th>LangChain AI应用</th><th>Python技能</th><th>课时</th></tr></thead><tbody><tr><td>1. Python启蒙</td><td>认识Python、变量/数据类型（数字、字符串）、print输出；用“AI代码小助手”答疑</td><td>数字与数线对应（如变量=数线点）</td><td>LangChain对话助手：生成基础代码示例（如<code>print(&quot;我的第一个坐标点：(2,3)&quot;)</code>）</td><td>变量定义、print函数</td><td>8</td></tr><tr><td>2. 空间坐标入门</td><td>turtle库绘图（直线、正方形、三角形）；坐标（x/y轴）与图形位置关联</td><td>坐标=数线二维扩展，图形边长=数学计算</td><td>LangChain代码提示：输入“画边长50的正方形”，生成turtle基础代码模板</td><td>turtle库、for循环</td><td>12</td></tr><tr><td>3. AI辅助几何创作</td><td>分组完成“我的几何画册”项目；用AI生成绘图代码初稿，修改参数（颜色、大小）</td><td>图形内角和、边长比例（空间缩放基础）</td><td>LangChain代码优化：上传初稿，AI提示“如何修改边长让正方形变长方形”</td><td>变量赋值、颜色参数调整</td><td>10</td></tr></tbody></table><h3 id="阶段2-进阶阶-11-13岁-2级-——空间推理与ai数据融合" tabindex="-1">阶段2：进阶阶（11-13岁，2级）——空间推理与AI数据融合 <a class="header-anchor" href="#阶段2-进阶阶-11-13岁-2级-——空间推理与ai数据融合" aria-label="Permalink to &quot;阶段2：进阶阶（11-13岁，2级）——空间推理与AI数据融合&quot;">​</a></h3><h4 id="核心目标-1" tabindex="-1">核心目标 <a class="header-anchor" href="#核心目标-1" aria-label="Permalink to &quot;核心目标&quot;">​</a></h4><p>强化Python逻辑（条件、循环、函数），结合LangChain实现“数据可视化+空间推理”，培养<strong>外在-动态空间技能</strong>（如心理旋转、视角转换），融合数学方程、数据统计。</p><table tabindex="0"><thead><tr><th>模块</th><th>核心内容</th><th>空间-数学融合点</th><th>LangChain AI应用</th><th>Python技能</th><th>课时</th></tr></thead><tbody><tr><td>1. 空间推理与函数</td><td>函数定义（如<code>draw_triangle(size)</code>）；实现图形旋转（心理旋转模拟）</td><td>旋转角度=数学角度计算，函数参数=比例控制</td><td>LangChain函数生成器：输入“旋转30度的三角形函数”，生成函数框架</td><td>函数定义、角度计算</td><td>12</td></tr><tr><td>2. AI数据可视化</td><td>用pandas处理简单数据（如“班级身高统计”）；绘制柱状图/折线图（空间数据呈现）</td><td>图表坐标轴=空间坐标，数据对比=数学比较</td><td>LangChain数据分析师：上传Excel数据，AI生成pandas绘图代码模板</td><td>pandas库、matplotlib库</td><td>16</td></tr><tr><td>3. 迷宫导航小项目</td><td>设计文本迷宫（坐标定位角色）；用LangChain优化路径逻辑（如“避开障碍物”）</td><td>路径规划=空间视角转换，步数计算=数学计数</td><td>LangChain逻辑助手：输入“迷宫角色从(1,1)到(5,5)的规则”，生成条件判断代码</td><td>条件语句、列表（迷宫地图）</td><td>18</td></tr></tbody></table><h3 id="阶段3-高阶-14-15岁-2级-——空间建模与langchain-ai开发" tabindex="-1">阶段3：高阶（14-15岁，2级）——空间建模与LangChain AI开发 <a class="header-anchor" href="#阶段3-高阶-14-15岁-2级-——空间建模与langchain-ai开发" aria-label="Permalink to &quot;阶段3：高阶（14-15岁，2级）——空间建模与LangChain AI开发&quot;">​</a></h3><h4 id="核心目标-2" tabindex="-1">核心目标 <a class="header-anchor" href="#核心目标-2" aria-label="Permalink to &quot;核心目标&quot;">​</a></h4><p>掌握Python模块化编程，用LangChain搭建“智能空间应用”（如导航助手、图形识别工具），培养<strong>空间建模能力</strong>，融合数学函数、AI逻辑（如prompt设计）。</p><table tabindex="0"><thead><tr><th>模块</th><th>核心内容</th><th>空间-数学融合点</th><th>LangChain AI应用</th><th>Python技能</th><th>课时</th></tr></thead><tbody><tr><td>1. LangChain基础与Prompt设计</td><td>认识LangChain（“AI积木”概念）；学习简单Prompt（如“生成绘制正方体的Python代码”）</td><td>正方体投影=空间透视，边长计算=函数关系</td><td>LangChain Prompt调试器：输入初稿，AI提示“补充‘3D效果’关键词让代码更精准”</td><td>LangChain安装、Prompt编写</td><td>14</td></tr><tr><td>2. 智能空间工具开发</td><td>项目1：“AI坐标导航助手”——输入起点/终点，LangChain生成路径计算代码</td><td>路径距离=数学勾股定理，坐标映射=空间建模</td><td>LangChain链条搭建：组合“对话模块+代码生成模块”，实现“提问→生成代码”流程</td><td>模块导入、LangChain Chains</td><td>20</td></tr><tr><td>3. 综合AI应用实战</td><td>项目2：“3D图形识别小工具”——上传几何图片，LangChain辅助生成识别代码（简化版）</td><td>图形特征提取=空间结构分析，识别逻辑=数学分类</td><td>LangChain向量存储：用简易向量库存储图形特征，实现“图片→特征匹配”</td><td>基础图像处理、向量基础</td><td>22</td></tr></tbody></table><h2 id="三、langchain-ai教学具体实施方案" tabindex="-1">三、LangChain AI教学具体实施方案 <a class="header-anchor" href="#三、langchain-ai教学具体实施方案" aria-label="Permalink to &quot;三、LangChain AI教学具体实施方案&quot;">​</a></h2><h3 id="_1-langchain少儿化改造-3个核心ai角色" tabindex="-1">1. LangChain少儿化改造：3个核心AI角色 <a class="header-anchor" href="#_1-langchain少儿化改造-3个核心ai角色" aria-label="Permalink to &quot;1. LangChain少儿化改造：3个核心AI角色&quot;">​</a></h3><p>将复杂的LangChain架构拆解为“角色化工具”，通过可视化平台（如自定义Web界面）让少儿操作，无需理解底层逻辑：</p><ul><li><p><strong>AI代码小助手（低阶）</strong>：</p><ul><li>功能：对话式生成基础代码、解答语法问题（如“怎么用turtle画圆？”）；</li><li>操作：在平台输入问题，AI输出带注释的简化代码（如<code>turtle.circle(50) # 半径50的圆，对应数学半径概念</code>）；</li><li>原理：基于LangChain的<code>ConversationChain</code>，预设“少儿编程知识库”，过滤复杂语法。</li></ul></li><li><p><strong>AI数据分析师（中阶）</strong>：</p><ul><li>功能：上传Excel/CSV数据，生成可视化代码模板（如柱状图、折线图）；</li><li>操作：1. 上传“班级座位坐标表”；2. 选择“画坐标分布图”；3. AI生成matplotlib代码，学生修改颜色/标题；</li><li>原理：基于LangChain的<code>CSVLoader</code>+<code>CodeGenerator</code>，预设数据可视化模板库。</li></ul></li><li><p><strong>AI应用设计师（高阶）</strong>：</p><ul><li>功能：组合“对话+代码+向量”模块，搭建简易智能应用；</li><li>操作：1. 在“模块面板”拖放“对话模块”“代码生成模块”；2. 输入“做一个迷宫导航工具”；3. AI生成模块连接逻辑，学生补充具体参数（如迷宫大小）；</li><li>原理：基于LangChain的<code>SequentialChain</code>，可视化模块拖拽界面降低搭建难度。</li></ul></li></ul><h3 id="_2-空间-数学-python-ai融合案例-中阶-迷宫导航项目" tabindex="-1">2. 空间-数学-Python-AI融合案例（中阶：迷宫导航项目） <a class="header-anchor" href="#_2-空间-数学-python-ai融合案例-中阶-迷宫导航项目" aria-label="Permalink to &quot;2. 空间-数学-Python-AI融合案例（中阶：迷宫导航项目）&quot;">​</a></h3><h4 id="教学流程-4课时-90分钟-课" tabindex="-1">教学流程（4课时，90分钟/课） <a class="header-anchor" href="#教学流程-4课时-90分钟-课" aria-label="Permalink to &quot;教学流程（4课时，90分钟/课）&quot;">​</a></h4><table tabindex="0"><thead><tr><th>步骤</th><th>教学活动</th><th>空间-数学联动</th><th>LangChain应用</th><th>学生输出</th></tr></thead><tbody><tr><td>1. 空间感知铺垫（1课时）</td><td>用积木搭建“实体迷宫”，标注起点(1,1)、终点(5,5)、障碍物(3,2)；讨论“如何绕开障碍”</td><td>迷宫坐标=空间位置，路径规划=心理旋转</td><td>无（实体操作）</td><td>实体迷宫图纸+路径说明</td></tr><tr><td>2. 数学逻辑转化（1课时）</td><td>将实体迷宫转化为Python列表（如<code>maze = [[0,1,0],[0,0,1]]</code>，0=通路，1=障碍）；计算步数</td><td>列表索引=坐标，步数=数学计数</td><td>AI代码小助手：输入“怎么用列表表示迷宫”，生成示例</td><td>迷宫列表代码</td></tr><tr><td>3. LangChain代码生成（1课时）</td><td>1. 在AI应用设计师平台拖放“对话模块”；2. 输入“生成迷宫角色从(1,1)到(5,5)的路径代码”；3. AI生成条件判断代码（如<code>if maze[x][y] == 0: 继续走</code>）</td><td>条件判断=路径规则，坐标变化=空间移动</td><td>LangChain生成代码初稿，学生补充“遇1则转向”逻辑</td><td>带路径逻辑的迷宫代码</td></tr><tr><td>4. 调试与展示（1课时）</td><td>1. 运行代码，观察角色是否走通；2. 用LangChain“错误排查助手”解决问题（如“角色卡在(3,2)”）；3. 小组展示，讲解“空间路径与代码逻辑的关系”</td><td>调试=空间逻辑修正，展示=空间-数学表达</td><td>LangChain错误提示：输入报错信息，AI提示“检查(3,2)的坐标判断条件”</td><td>可运行的迷宫导航代码+讲解视频</td></tr></tbody></table><h3 id="_3-教学评估-四维能力-rubric量表" tabindex="-1">3. 教学评估：四维能力 rubric量表 <a class="header-anchor" href="#_3-教学评估-四维能力-rubric量表" aria-label="Permalink to &quot;3. 教学评估：四维能力 rubric量表&quot;">​</a></h3><table tabindex="0"><thead><tr><th>评估维度</th><th>Level 1（基础）</th><th>Level 2（达标）</th><th>Level 3（优秀）</th></tr></thead><tbody><tr><td>空间技能</td><td>能识别简单坐标（如(2,3)对应位置）</td><td>能设计2×2迷宫，解释路径的空间逻辑</td><td>能优化3D图形代码，体现空间透视效果</td></tr><tr><td>数学能力</td><td>能将数线对应到坐标（如x=3对应数线3）</td><td>能计算图形旋转角度、数据统计（如平均身高）</td><td>能用电学函数（如y=2x）控制图形大小变化</td></tr><tr><td>Python技能</td><td>能修改代码参数（如turtle颜色）</td><td>能独立编写带函数的代码（如draw_square()）</td><td>能模块化开发小工具（如分文件存储代码）</td></tr><tr><td>LangChain应用</td><td>能使用AI小助手生成基础代码</td><td>能调试AI生成的数据可视化代码</td><td>能独立搭建“对话→代码”的AI应用链条</td></tr></tbody></table><h2 id="四、配套教学资源" tabindex="-1">四、配套教学资源 <a class="header-anchor" href="#四、配套教学资源" aria-label="Permalink to &quot;四、配套教学资源&quot;">​</a></h2><ol><li><strong>工具包</strong>： <ul><li>低阶：坐标纸、几何积木、Python-turtle可视化软件；</li><li>中高阶：LangChain少儿版平台（自定义Web界面）、Excel数据模板、简易图像处理工具。</li></ul></li><li><strong>安全保障</strong>： <ul><li>LangChain平台预设“少儿安全知识库”，过滤恶意代码；</li><li>所有AI生成代码需教师审核后，学生方可运行。</li></ul></li><li><strong>拓展资源</strong>： <ul><li>课后项目：“家庭空间地图”——用Python+LangChain生成家庭房间坐标图；</li><li>竞赛通道：每年举办“AI空间小创客”比赛，评选优秀智能应用（如导航工具、图形识别工具）。</li></ul></li></ol>',36)])])}const b=a(e,[["render",i]]);export{u as __pageData,b as default};
